Ui.Script:

NUM_ALWAYS_UP_ROWS = 0;

-- Vertical pitch between rows, and the icon's box. Ours, not measured from the reference:
-- this frame is being written rather than transcribed, and the numbers below are what make
-- a two- or three-row readout sit legibly under the top edge.
WORLD_STATE_ROW_HEIGHT = 22;
WORLD_STATE_ICON_SIZE = 20;

-- Rebuild the readout from the host's list. Cheap enough to run whole on every fire: the
-- list is at most a handful of rows, and the events are a zone's worth apart.
function WorldStateAlwaysUpFrame_Update()
    local numUI = GetNumWorldStateUI();

    -- Grow the row pool on demand and never shrink it, the way every pooled list here
    -- does: the tail from a busier zone is parked hidden rather than destroyed.
    if ( numUI > NUM_ALWAYS_UP_ROWS ) then
        for i = NUM_ALWAYS_UP_ROWS + 1, numUI do
            local row = CreateFrame("Frame", "WorldStateAlwaysUpFrame" .. i,
                WorldStateAlwaysUpFrame, "WorldStateAlwaysUpTemplate");
            row:SetPoint("TOP", WorldStateAlwaysUpFrame, "TOP", 0,
                -(i - 1) * WORLD_STATE_ROW_HEIGHT);
        end
        NUM_ALWAYS_UP_ROWS = numUI;
    end

    for i = 1, NUM_ALWAYS_UP_ROWS do
        local row = getglobal("WorldStateAlwaysUpFrame" .. i);
        if ( i > numUI ) then
            row:Hide();
        else
            local uiState, text, icon, dynamicIcon, tooltip, dynamicTooltip = GetWorldStateUIInfo(i);
            local iconTexture = getglobal(row:GetName() .. "Icon");
            local textString = getglobal(row:GetName() .. "Text");

            -- The dynamic icon replaces the static one while the row's own state is live.
            -- A row with neither draws no icon at all and the text takes the whole width;
            -- the reference's own data has several such rows (the progress line).
            local shown = icon;
            row.tooltip = tooltip;
            if ( dynamicIcon ~= "" and uiState ~= 0 ) then
                shown = dynamicIcon;
                if ( dynamicTooltip ~= "" ) then
                    row.tooltip = dynamicTooltip;
                end
            end
            -- ClearAllPoints first: SetPoint ADDS an anchor, and the template already
            -- seated the text against the icon.
            textString:ClearAllPoints();
            if ( shown == "" ) then
                iconTexture:Hide();
                textString:SetPoint("LEFT", row, "LEFT", 0, 0);
            else
                iconTexture:SetTexture(shown);
                iconTexture:Show();
                textString:SetPoint("LEFT", iconTexture, "RIGHT", 4, 0);
            end
            textString:SetText(text);
            row:Show();
        end
    end

    -- The container is only as tall as the rows it shows, and disappears entirely when
    -- there are none — this frame has no chrome of its own to leave behind.
    if ( numUI > 0 ) then
        WorldStateAlwaysUpFrame:SetHeight(numUI * WORLD_STATE_ROW_HEIGHT);
        WorldStateAlwaysUpFrame:Show();
    else
        WorldStateAlwaysUpFrame:Hide();
    end
end

function WorldStateAlwaysUpFrame_OnEvent()
    WorldStateAlwaysUpFrame_Update();
end

Scripts.OnEnter:
if ( this.tooltip and this.tooltip ~= "" ) then
    GameTooltip:SetOwner(this, "ANCHOR_BOTTOMLEFT");
    GameTooltip:SetText(this.tooltip);
    GameTooltip:Show();
end

Scripts.OnLoad:
-- UPDATE_WORLD_STATES is the reference's own event for this list (0x20e). The
-- entering-world fire is what paints the readout on a login that lands inside a
-- scope the server has already sent states for.
this:RegisterEvent("UPDATE_WORLD_STATES");
this:RegisterEvent("PLAYER_ENTERING_WORLD");
